      if(document.getElementById('ch-instagram').checked) channels.push('Instagram');
      if(document.getElementById('ch-tiktok').checked) channels.push('TikTok');
      if(document.getElementById('ch-blog').checked) channels.push('Blog/Web');
      if(document.getElementById('ch-newsletter').checked) channels.push('Newsletter');

      if(channels.length === 0) {
        alert('Please toggle at least one distribution channel.');
        return;
      }

      // Build Context-driven dynamic output structure
      generatedData = {
        recipe: recipe,
        hook: hook,
        audience: aud,
        complexity: comp,
        channels: channels,
        titles: [
          { t: `The Ultimate ${recipe} for ${aud}`, d: `Direct value framing optimized for web title tags.` },
          { t: `Better than takeout ${recipe} (${comp})`, d: `High-curiosity click trigger for social channels.` }
        ],
        ingredients: [
          { t: "Confirm specialized/niche item alternatives", d: `Provide immediate substitutes to accommodate ${aud}.` },
          { t: "Metric vs Imperial clean toggle check", d: "Ensure scaling logic matches cross-regional expectations." }
        ],
        socialAngles: [],
        hashtags: [],
        risks: [
          { t: "Missing Hero Header Asset", d: "Requires high-resolution landscape photo for main card presentation.", r: "High" }
        ]
      };

      // Populate Channel-Specific logic paths
      channels.forEach(ch => {
        if(ch === 'Instagram') {
          generatedData.socialAngles.push({ t: "IG Reel Carousel Anchor", d: `Visual asset step breakdown highlighting: "${hook}"` });
          generatedData.hashtags.push({ t: "#Foodstagram #RecipeShare #HomeCooking", d: "Broad visibility tier" });
          generatedData.risks.push({ t: "Missing vertical 9:16 asset for IG Stories", d: "Crucial for initial click-through traffic loop.", r: "Medium" });
        }
        if(ch === 'TikTok') {
          generatedData.socialAngles.push({ t: "ASMR/First Bite Hook Trend", d: `Open video loop directly on: "${hook}" within 2.5 seconds.` });
          generatedData.hashtags.push({ t: `#FoodTikTok #${recipe.replace(/\s+/g, '')} #EasyRecipes`, d: "Algorithmic niche tags" });
          generatedData.risks.push({ t: "Missing fast-paced high BPM audio track matching", d: "Risk of low organic retention if audio hooks lag.", r: "High" });
        }
        if(ch === 'Blog/Web') {
          generatedData.socialAngles.push({ t: "SEO Long-form Answer Box Target", d: `Format introductory copy to capture: "How do you make ${recipe} quickly?"` });
          generatedData.hashtags.push({ t: "SEO Meta: Recipe Schema Format", d: "Structural JSON-LD payload confirmation marker" });
          generatedData.risks.push({ t: "Missing Jump-to-Recipe functional logic link", d: "Increases bounce rates significantly for mobile users.", r: "High" });
        }
        if(ch === 'Newsletter') {
          generatedData.socialAngles.push({ t: "Exclusive Insider Variation", d: `Positioning line: "The exact trick I use when making this ${recipe} for special occasions."` });
          generatedData.hashtags.push({ t: "Subject Line: Pre-header optimization slot", d: "Value teaser line insertion check" });
        }
      });

      // Render items out into distinct functional checklist blocks
      renderChecklist('title-checklist', generatedData.titles);
      renderChecklist('ingredient-checklist', generatedData.ingredients);
      renderChecklist('social-checklist', generatedData.socialAngles);
      renderChecklist('hashtag-checklist', generatedData.hashtags);
      renderChecklist('asset-checklist', generatedData.risks, true);

      // Unhide targeted element UI blocks
      document.getElementById('action-bar').classList.remove('hidden');
      document.getElementById('output-container').classList.remove('hidden');
    }

    function renderChecklist(elementId, items, isRisk = false) {
      const container = document.getElementById(elementId);
      container.innerHTML = '';

      items.forEach((item, index) => {
        const div = document.createElement('div');
        div.className = 'checklist-item';

        let badgeHtml = '';
        if (isRisk && item.r) {
          const badgeClass = item.r === 'High' ? 'badge-danger' : 'badge-warning';
          badgeHtml = `<span class="badge ${badgeClass}">${item.r} Risk</span>`;
        }

        div.innerHTML = `
          <input type="checkbox" id="${elementId}-${index}">
          <div class="checklist-content">
            <div class="checklist-title">${item.t}${badgeHtml}</div>
            <div class="checklist-desc">${item.d}</div>
          </div>
        `;
        container.appendChild(div);
      });
    }

    function buildTextBrief() {
      let txt = `RECIPE CONTENT READINESS BRIEF\n`;
      txt += `====================================\n`;
      txt += `Recipe: ${generatedData.recipe}\n`;
      txt += `Hook/Serving Note: ${generatedData.hook}\n`;
      txt += `Audience: ${generatedData.audience} (${generatedData.complexity})\n`;
      txt += `Channels: ${generatedData.channels.join(', ')}\n\n`;

      txt += `1. TITLE PROMISES\n`;
      generatedData.titles.forEach(t => txt += `- [ ] ${t.t} (${t.d})\n`);
      txt += `\n2. INGREDIENT CLARITY\n`;
      generatedData.ingredients.forEach(i => txt += `- [ ] ${i.t} (${i.d})\n`);
      txt += `\n3. SOCIAL POST ANGLES\n`;
      generatedData.socialAngles.forEach(s => txt += `- [ ] ${s.t} (${s.d})\n`);
      txt += `\n4. HASHTAG BUCKETS\n`;
      generatedData.hashtags.forEach(h => txt += `- [ ] ${h.t} (${h.d})\n`);
      txt += `\n5. MISSING ASSETS & RISK FLAGS\n`;
      generatedData.risks.forEach(r => txt += `- [ ] [${r.r} Risk] ${r.t} (${r.d})\n`);

      return txt;
    }

    function copyBrief() {
      const text = buildTextBrief();
      navigator.clipboard.writeText(text).then(() => {
        const toast = document.getElementById('toast');
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 2000);
      });
    }

    function downloadBrief() {
      const text = buildTextBrief();
      const blob = new Blob([text], { type: 'text/plain' });
      const anchor = document.createElement('a');
      anchor.download = `${generatedData.recipe.toLowerCase().replace(/\s+/g, '-')}-readiness-brief.txt`;
      anchor.href = window.URL.createObjectURL(blob);
      anchor.click();
      window.URL.revokeObjectURL(anchor.href);
    }
  </script>
</body>
</html>
